UPDATE merchant_deposit
SET frozen_amount = frozen_amount + #{amount}, update_time = NOW()
WHERE merchant_id = #{merchantId}
  AND (total_amount - frozen_amount) >= #{amount}

UPDATE merchant_deposit
SET frozen_amount = frozen_amount - #{amount}, update_time = NOW()
WHERE merchant_id = #{merchantId}
  AND frozen_amount >= #{amount}

UPDATE merchant_deposit
SET frozen_amount = frozen_amount - #{amount},
    total_amount = total_amount - #{amount},
    update_time = NOW()
WHERE merchant_id = #{merchantId}
  AND frozen_amount >= #{amount}
  AND total_amount >= #{amount}
